define({"topics":[{"title":"Replacing an SKF table limit switch","shortdesc":"<p class=\"shortdesc\">Removes the up-limit or down-limit switch from a fixed table and installs a replacement switch. This procedure is applicable to fixed tables with an SKF actuator (<span class=\"ph\">5779964<\/span>).<\/p>","href":"t_ReplacingAnSKFTableLimitSwitch.html","attributes":{"data-id":"id_2013821"},"menu":{"hasChildren":true},"tocID":"id_2013821-d46e439932","next":"id_2013821-d46e439932"},{"title":"Replacing an EHA table limit switch","shortdesc":"<p class=\"shortdesc\">Removes the up-limit or down-limit switch from a fixed table and installs a replacement switch. This procedure is applicable to fixed tables with an EHA actuator (<span class=\"ph\">5451412-20<\/span>).<\/p>","href":"t_ReplacingAnEHATableLimitSwitch.html","attributes":{"data-id":"id_2013822"},"menu":{"hasChildren":true},"tocID":"id_2013822-d46e440248","next":"id_2013822-d46e440248"}]});